INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES
(34996, 18, 0, 'koKR', 'Przyjmijcie te skrzynie w nagrodę i niech ich zawartość wiernie wam służy w kampanii przeciwko Arthasowi w sercu Cytadeli Lodowej Korony!'),
(36095, 1, 0, 'koKR', 'Przyjmijcie te skrzynie w nagrodę i niech ich zawartość wiernie wam służy w kampanii przeciwko Arthasowi w sercu Cytadeli Lodowej Korony!');
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(35144, 'koKR', 'Draenei z Exodaru wiwatują na cześć $n.', 'Draenei z Exodaru wiwatują na cześć $n.', 0),
(35145, 'koKR', 'Krasnoludy z Żelaznej Kuźni zaczynają wiwatować na cześć $n.', 'Krasnoludy z Żelaznej Kuźni zaczynają wiwatować na cześć $n.', 0),
(35146, 'koKR', 'Gnomy z Gnomoregan wiwatują na cześć $n.', 'Gnomy z Gnomoregan wiwatują na cześć $n.', 0),
(35147, 'koKR', 'Ludzie z Wichrogrodu wiwatują na cześć $n.', 'Ludzie z Wichrogrodu wiwatują na cześć $n.', 0),
(35148, 'koKR', 'Nocne elfy z Darnassus wiwatują na cześć $n.', 'Nocne elfy z Darnassus wiwatują na cześć $n.', 0),
(35161, 'koKR', 'Widzowie z Przymierza wiwatują na cześć $n.', 'Widzowie z Przymierza wiwatują na cześć $n.', 0),
(35322, 'koKR', 'Nie gustuję w takich igrzyskach, Tirionie. Mimo to... ufam, że spiszą się znakomicie.', '', 0),
(35324, 'koKR', 'Znakomicie? Ha! Z przyjemnością popatrzę, jak twoi słabowici czempioni przegrywają, człowieku.', '', 0),
(35325, 'koKR', 'Garoszu, dość.', '', 0),
(35326, 'koKR', 'Walcz dzielnie, Hordo! Lok\'tar Ogar!', '', 0),
(35327, 'koKR', 'Wreszcie walka warta oglądania.', '', 0),
(35328, 'koKR', 'Nie przybyłem tu, by patrzeć, jak zwierzęta bezmyślnie rozszarpują się nawzajem, Tirionie.', '', 0),
(35550, 'koKR', 'Nie stójcie tak, zabijcie go!', '', 0),
(35551, 'koKR', 'Rozerwijcie go na strzępy!', '', 0),
(35684, 'koKR', 'HA!', '', 0),
(35685, 'koKR', 'Żadne wyzwanie.', '', 0),
(35686, 'koKR', 'Bezwartościowy cherlak.', '', 0),
(35687, 'koKR', 'To wszystko, na co stać Hordę?', '', 0),
(35688, 'koKR', 'Przymierze nie potrzebuje pomocy demonicznego władcy, żeby rozprawić się z hordzkim plugastwem! Chodź tu, świnio!', '', 0),
(35689, 'koKR', 'Walczcie ku chwale Przymierza, bohaterowie! Czcijcie swojego króla i swój lud!', '', 0),
(35690, 'koKR', 'Splamiono nasz honor! Rzucają przeciw nam bezpodstawne oskarżenia i fałszywe zarzuty. Żądam sprawiedliwości! Pozwól moim czempionom walczyć w miejsce twoich rycerzy, Tirionie. Wyzywamy Hordę!', '', 0),
(35691, 'koKR', 'CHWAŁA PRZYMIERZU!', '', 0),
(35692, 'koKR', 'Nawet najpotężniejsze sługi Króla Lisza nie zdołają oprzeć się Przymierzu. Chwała naszym zwycięzcom!', '', 0),
(35693, 'koKR', 'Twoje bestie nie dorównają moim czempionom, Tirionie!', '', 0),
(35694, 'koKR', 'Słabeusz!', '', 0),
(35697, 'koKR', 'Pokonany...', '', 0),
(35699, 'koKR', 'Zdradzieckie psy Przymierza! Przyzywacie demonicznego władcę przeciwko wojownikom Hordy? Wasza śmierć będzie szybka!', '', 0),
(35701, 'koKR', 'Nie okazujcie im litości, czempioni Hordy! LOK\'TAR OGAR!', '', 0),
(35703, 'koKR', 'Horda żąda sprawiedliwości! Wyzywamy Przymierze! Pozwól nam walczyć w miejsce twoich rycerzy, paladynie. Pokażemy tym psom, co znaczy obrażać Hordę.', '', 0),
(35705, 'koKR', 'To był tylko przedsmak tego, co przyniesie przyszłość. ZA HORDĘ!', '', 0),
(35706, 'koKR', 'Wciąż wątpisz w potęgę Hordy, paladynie? Zmierzymy się z każdym, kto się zgłosi!', '', 0),
(35707, 'koKR', 'W Kręgu Krwi widziałem godniejsze wyzwania. Marnujesz nasz czas, paladynie.', '', 0),
(35708, 'koKR', 'Witajcie, czempioni! Usłyszeliście wezwanie Krucjaty Argentu i odważnie na nie odpowiedzieliście! To tutaj, w Koloseum Krzyżowców, staniecie przed swoimi największymi wyzwaniami. Ci z was, którzy przetrwają trudy koloseum, dołączą do Krucjaty Argentu w jej marszu na Cytadelę Lodowej Korony.', '', 0),
(35710, 'koKR', 'Prosto z najgłębszych, najciemniejszych jaskiń Burzowych Szczytów – Gormok Palownik! Do boju, bohaterowie!', '', 0),
(35711, 'koKR', 'Przygotujcie się, bohaterowie, bo na arenę wkraczają bliźniacze postrachy, Żrącopaszczy i Strasznołuski!', '', 0),
(35712, 'koKR', 'Samo powietrze zamarza, gdy przedstawiamy kolejnego zawodnika – oto Lodowy Skowyt! Zabijcie albo zgińcie, czempioni!', '', 0),
(35713, 'koKR', 'Potworna menażeria została pokonana!', '', 0),
(35714, 'koKR', 'Tragiczne... Walczyli dzielnie, lecz bestie Północnej Grani zatriumfowały. Uczcijmy chwilą ciszy naszych poległych bohaterów.', '', 0),
(35715, 'koKR', 'Wielki czarnoksiężnik Wilfred Bombik przyzwie wasze kolejne wyzwanie. Czekajcie na jego wejście.', '', 0),
(35716, 'koKR', 'Szybko, bohaterowie, zniszczcie demonicznego władcę, zanim otworzy portal do swojego wypaczonego demonicznego wymiaru!', '', 0),
(35717, 'koKR', 'Strata Wilfreda Bombika, choć niefortunna, powinna być nauczką dla tych, którzy ważą się igrać z mroczną magią. Tak czy inaczej, zwyciężyliście i teraz musicie stawić czoła kolejnemu wyzwaniu.', '', 0),
(35718, 'koKR', 'Spokój! Opanujcie się! Nie ma tu żadnego spisku! Czarnoksiężnik działał z własnej woli, bez żadnego wpływu Przymierza. Turniej musi trwać dalej!', '', 0),
(35719, 'koKR', 'Następna bitwa stoczona zostanie z najpotężniejszymi rycerzami Krucjaty Argentu! Tylko pokonując ich, zostaniecie uznani za godnych...', '', 0),
(35720, 'koKR', 'Dobrze więc. Zgadzam się. Walczcie z honorem!', '', 0),
(35721, 'koKR', 'Płytkie i tragiczne zwycięstwo. Straty poniesione dziś osłabiły nas wszystkich. Kto poza Królem Liszem mógłby skorzystać na takiej głupocie? Wielcy wojownicy stracili życie. I po co? Prawdziwe zagrożenie wciąż czeka przed nami – Król Lisz czeka na nas wszystkich w śmierci.', '', 0),
(35722, 'koKR', 'Tylko współpracując, pokonacie ostatnie wyzwanie. Z głębin Lodowej Korony przybywają dwie z najpotężniejszych poruczniczek Plagi: groźne val\'kyrie, skrzydlate zwiastunki Króla Lisza!', '', 0),
(35723, 'koKR', 'Król Lisz otrzymał potężny cios! Udowodniliście, że jesteście sprawnymi czempionami Krucjaty Argentu. Razem uderzymy na Cytadelę Lodowej Korony i zniszczymy resztki Plagi! Nie ma wyzwania, któremu nie sprostamy zjednoczeni!', '', 0),
(35724, 'koKR', 'Arthasie! Jesteś w beznadziejnej mniejszości! Złóż Ostrze Mrozu, a zapewnię ci sprawiedliwą śmierć.', '', 0),
(35794, 'koKR', 'Dobra robota, Hordo!', '', 0),
(35795, 'koKR', 'Dobrze walczyliście.', '', 0),
(35796, 'koKR', 'Moje gratulacje, czempioni. Przez próby zarówno zaplanowane, jak i niespodziewane, zatriumfowaliście.', '', 0),
(35797, 'koKR', 'Idźcie teraz odpocząć, zasłużyliście.', '', 0),
(36129, 'koKR', 'Czempioni, żyjecie! Nie tylko pokonaliście każde wyzwanie Próby Krzyżowca, ale też pokrzyżowaliście plany Arthasa! Wasza zręczność i spryt okażą się potężną bronią przeciwko Pladze. Dobra robota! Pozwólcie, by jeden z magów Krucjaty przeniósł was na powierzchnię!', '', 0),
(37739, 'koKR', 'Lok\'tar!', 'Lok\'tar!', 0);
